// Récupérer les données depuis Generate Prompt (qui contient le prompt)
const promptData = $('✨ Generate Prompt').first().json;

// Récupérer TOUTES les images lues
const allItems = $input.all();

// Format OpenAI/OpenRouter : un tableau de parts typées
const content = [
  { type: 'text', text: promptData.prompt }
];

// Chaque image est envoyée en data URI base64
for (const item of allItems) {
  const binaryData = item.binary?.data?.data;
  if (binaryData) {
    const mimeType = item.json.mimeType || 'image/png';
    content.push({
      type: 'image_url',
      image_url: {
        url: `data:${mimeType};base64,${binaryData}`,
        detail: 'high'
      }
    });
  }
}

if (content.length === 1) {
  return [{
    json: {
      error: 'No images found!',
      totalItems: allItems.length
    }
  }];
}

// Build OpenRouter API body
// max_tokens est indispensable : OpenRouter reserve du credit sur le PIRE cas,
// pas sur la consommation reelle. Sans plafond, la requete reclame le maximum
// du modele (65536 tokens) et est refusee en 402 des que le solde est modeste,
// alors que l'image ne coutera que quelques centimes. Une image pese ~7000
// tokens de sortie : 16384 laisse une marge large.
const apiBody = {
  model: 'openai/gpt-5.4-image-2',
  modalities: ['image', 'text'],
  max_tokens: 16384,
  messages: [
    {
      role: 'user',
      content: content
    }
  ]
};

return [{
  json: {
    ...promptData,
    apiBody,
    imagesCount: content.length - 1
  }
}];

const response = $input.first().json;
const promptData = $('✨ Generate Prompt').item.json;

let imageBase64 = null;
let textResponse = '';

// Erreur renvoyée par OpenRouter (200 avec corps d'erreur, ou relais fournisseur)
if (response.error) {
  const msg = response.error.message || JSON.stringify(response.error);
  throw new Error('OpenRouter error: ' + msg);
}

const choice = (response.choices || [])[0];
const message = choice ? choice.message : null;

if (message) {
  if (typeof message.content === 'string') {
    textResponse = message.content;
  }
  if (message.refusal) {
    throw new Error('Model refused the request: ' + message.refusal);
  }
  // L'image est dans choices[0].message.images[].image_url.url
  for (const img of (message.images || [])) {
    const url = img?.image_url?.url;
    if (!url) continue;
    if (url.startsWith('data:')) {
      // data URI complet : on ne garde que la charge base64
      imageBase64 = url.slice(url.indexOf(',') + 1);
    } else {
      throw new Error('Image returned as remote URL, not base64: ' + url.slice(0, 120));
    }
  }
}

if (!imageBase64) {
  const reason = choice ? (choice.finish_reason || 'unknown') : 'no choice';
  throw new Error(
    'No image in API response (finish_reason=' + reason + '): ' +
    JSON.stringify(response).substring(0, 500)
  );
}

return [{
  json: {
    jobId: promptData.jobId,
    outputPath: promptData.outputPath,
    fileName: promptData.fileName,
    nameWithoutExt: promptData.nameWithoutExt,
    textResponse,
    success: true
  },
  binary: {
    data: {
      data: imageBase64,
      mimeType: 'image/png',
      fileName: promptData.nameWithoutExt + '_generated.png'
    }
  }
}];

const extractData = $('🖼️ Extract Image').item.json;
const promptData = $('✨ Generate Prompt').item.json;

return [{
  json: {
    status: '✅ SUCCESS',
    jobId: extractData.jobId,
    input: promptData.fileName,
    output: extractData.outputPath,
    product: promptData.productName,
    type: promptData.garmentType,
    size: promptData.sizeInfo.label,
    completedAt: new Date().toISOString()
  }
}];

// Get the error and job ID from context
const errorMessage = $input.first().json?.error?.message || $execution?.error?.message || 'Unknown error during processing';

// Try to get jobId from various possible sources
let jobId = null;
try {
  jobId = $('🏷️ Parse Job Data2').item?.json?.jobId;
} catch (e) {
  try {
    jobId = $('📝 Update Processing').item?.json?.id;
  } catch (e2) {
    try {
      jobId = $('🔍 Filter Pending').item?.json?.id;
    } catch (e3) {
      // No job ID found
    }
  }
}

if (!jobId) {
  throw new Error('Cannot update error status: no job ID found. Original error: ' + errorMessage);
}

return [{
  json: {
    jobId,
    errorMessage: errorMessage.substring(0, 1000)
  }
}];

const job = $('Postgres Trigger').first().json.payload;
const jobId = job.id;

// Chemins Docker
const inputBasePath = '/clothify_shared/input_image/';
const outputBasePath = '/clothify_shared/output_image/';

// Gestion robuste des inputs
let inputFilePaths = job.input_file_paths || [];
if (typeof inputFilePaths === 'string') {
  inputFilePaths = JSON.parse(inputFilePaths);
}

// Normalisation des entrées
const garmentType = String(job.garment || 'other').toLowerCase();
const sizeCode = String(job.size || '2');
// --- NEW: Extraction de l'angle (défaut sur 'face' si vide) ---
const angleCode = String(job.angle || 'face').toLowerCase().trim(); 

const productName = job.product_name || 'product';
const customPrompt = job.custom_prompt || null;

if (!inputFilePaths || inputFilePaths.length === 0) {
  throw new Error('No input files found for job: ' + jobId);
}

// Logique de taille
function getSizeInfo(code) {
  switch(code) {
    case '1': return { code: 'XS', label: 'Extra Small', bodyDescription: 'petite slim build, 155-160cm', fit: 'fitted' };
    case '3': return { code: 'L', label: 'Large', bodyDescription: 'athletic build, 175-180cm', fit: 'comfortable fit' };
    case '4': return { code: 'XL', label: 'Extra Large', bodyDescription: 'plus size, 170-175cm', fit: 'relaxed fit' };
    default: return { code: 'S/M', label: 'Small/Medium', bodyDescription: 'average build, 165-170cm', fit: 'regular fit' };
  }
}

// --- NEW: Logique d'angle de caméra ---
function getAngleInfo(code) {
  // On matche les clés exactes fournies (face, profil, dos, trois-quarts face)
  switch(code) {
    case 'profil': 
      return { 
        code: 'profil', 
        prompt: "full side profile (90° yaw)", 
        technical_description: 'Side View' 
      };
    case 'dos': 
      return { 
        code: 'dos', 
        prompt: "direct back view (180° yaw)", 
        technical_description: 'Back View' 
      };
    case 'trois-quarts face': 
      return { 
        code: 'trois-quarts face', 
        prompt: "standard three-quarter front view (~45° yaw)", 
        technical_description: '3/4 View' 
      };
    case 'face':
    default: 
      // Cas par défaut (face)
      return { 
        code: 'face', 
        prompt: "direct front view (0° yaw)", 
        technical_description: 'Front View' 
      };
  }
}

// Logique de type (Vêtement vs Objet Custom)
function getTypeInfo(type) {
  switch(type) {
    case 'echarpe': return { category: 'accessory', placement: 'draped around neck', focus: 'texture and pattern' };
    case 'pull': return { category: 'top', placement: 'worn on upper body', focus: 'knit texture' };
    case 'tshirt': return { category: 'top', placement: 'casual upper body', focus: 'fabric drape' };
    case 'chemise': return { category: 'top', placement: 'buttoned, collar visible', focus: 'collar, buttons' };
    case 'veste': return { category: 'outerwear', placement: 'worn open', focus: 'structure, lapels' };
    case 'manteau': return { category: 'outerwear', placement: 'full length', focus: 'silhouette' };
    case 'pantalon': return { category: 'bottom', placement: 'full length lower body', focus: 'waist fit, leg line' };
    case 'jean': return { category: 'bottom', placement: 'casual stance', focus: 'denim texture' };
    case 'short': return { category: 'bottom', placement: 'thigh length', focus: 'fit and proportion' };
    case 'jupe': return { category: 'bottom', placement: 'movement captured', focus: 'flow, silhouette' };
    case 'robe': return { category: 'dress', placement: 'full body elegant', focus: 'silhouette, fabric' };
    case 'bonnet': return { category: 'accessory', placement: 'on head', focus: 'fit and texture' };
    case 'casquette': return { category: 'accessory', placement: 'on head front', focus: 'shape' };
    case 'sac': return { category: 'accessory', placement: 'held or shoulder', focus: 'shape, material' };

    // Cas par défaut pour objets inconnus
    default: return { 
      category: 'custom', 
      placement: 'integrated naturally into the scene matching its function', 
      focus: 'realistic texture, lighting match and high fidelity details' 
    };
  }
}

const sizeInfo = getSizeInfo(sizeCode);
const typeInfo = getTypeInfo(garmentType);
// --- NEW: Résolution de l'angle ---
const angleInfo = getAngleInfo(angleCode);

// Construction des chemins de sortie
const primaryInputPath = inputFilePaths[0];
const fileName = primaryInputPath.split('/').pop();
const dotIndex = fileName.lastIndexOf('.');
const nameWithoutExt = fileName.substring(0, dotIndex);
const outputPath = outputBasePath + nameWithoutExt + '_generated.png';

// Génération du tableau de résultats
const results = [];
for (let i = 0; i < inputFilePaths.length; i++) {
  const relativePath = inputFilePaths[i];
  const fName = relativePath.split('/').pop();
  const absolutePath = inputBasePath + fName;
  const extIndex = fName.lastIndexOf('.');
  const ext = fName.substring(extIndex + 1).toLowerCase();

  let mime = 'image/jpeg';
  if (ext === 'png') mime = 'image/png';
  else if (ext === 'webp') mime = 'image/webp';

  results.push({
    json: {
      jobId,
      inputFilePaths,
      imagePath: absolutePath,
      imageIndex: i,
      totalImages: inputFilePaths.length,
      mimeType: mime,
      outputPath,
      productName,
      garmentType,
      sizeCode,
      // --- NEW: Passage des données de l'angle au node suivant ---
      angleCode, 
      angleInfo,
      sizeInfo,
      typeInfo,
      customPrompt,
      discordMessageId: job.discord_message_id,
      userId: job.user_id
    }
  });
}

return results;

const data = $input.first().json;
const { productName, garmentType, sizeInfo, typeInfo, customPrompt } = data;

let prompt;

// LOGIQUE CHIRURGICALE :
// Si l'objet est 'custom' (inconnu), on remplace "GARMENT" par "ITEM" dans le prompt.
const itemLabel = (typeInfo.category === 'custom') ? 'ITEM' : 'GARMENT';

if (customPrompt && customPrompt.trim() !== '') {
  // Cas 1 : Prompt utilisateur manuel (Priorité absolue)
  prompt = `${customPrompt}\n\nAdditional context:\n- Product: ${productName.replace(/_/g, ' ')}\n- Type: ${garmentType}\n- Model size: ${sizeInfo.label} (${sizeInfo.bodyDescription})\n\nKeep original design and colors. Professional e-commerce style.`;
} else {
  // Cas 2 : Génération automatique (Standard ou Objet Custom)
prompt = `
--- VISUAL SPECIFICATION SHEET ---
TARGET: Luxury E-Commerce Asset (NET-A-PORTER Aesthetic)
ANCHOR_REFERENCE: Attached Image (Source of Truth for Design & Color)

1. [SUBJECT SPECIFICATIONS]
   - Model Entity: Realistic ${$('Postgres Trigger').first().json.payload.genre} model.
   - Body Metrics: ${sizeInfo.bodyDescription}, ${sizeInfo.label}.
   - Item Identification: ${garmentType}.
   - Interaction/Fit: ${itemLabel}: ${typeInfo.placement}. The item must sit naturally on the body.
   - Visual Focus: ${typeInfo.focus}.

2. [SCENE & PHYSICS]
   - Environment: A realistic gray cyclorama wall.
   - Lighting: Soft large softbox lighting creating smooth gradients.
   - Physics: Fabric must drape naturally, respecting gravity.

3. [HARD CONSTRAINTS]
   - CONSTRAINT: Head and face are STRICTLY out of frame (Neck-down crop).
   - CONSTRAINT: Body orientation must ${$input.first().json.angleInfo.prompt}.
   - CONSTRAINT: Do not alter the product's design, color, or texture. The Anchor is the absolute truth.

4. [TECHNICAL CONFIGURATION]
   - Camera: 85mm Lens (Flattering portrait compression).
   - Framing: Frame starts strictly below the jawline.
   - Style: Photorealistic, 4K resolution, sharp textures.
--- END SPEC ---
`}

return [{ json: { ...data, prompt } }];

